<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { flattenTree } from './processing-tasks.js'
const props=defineProps({directories:{type:Array,default:()=>[]},rootLabel:{type:String,required:true},selected:{type:Number,default:0},canCreate:Boolean,canUpdate:Boolean,canDelete:Boolean,readonly:Boolean})
const emit=defineEmits(['select','action','sort'])
const tree=ref(null),menu=ref(null)
const treeData=computed(()=>{const build=parent=>props.directories.filter(d=>d.parentId===parent).slice().sort((a,b)=>a.sortOrder-b.sortOrder||a.id-b.id).map(d=>({...d,children:build(d.id)}));return [{id:0,name:props.rootLabel,children:build(null)}]})
watch(()=>props.selected,async id=>{await nextTick();tree.value?.setCurrentKey(id)},{immediate:true})
function select(node){emit('select',node.id);menu.value=null}
function open(event,node){event.preventDefault();event.stopPropagation();select(node);if(props.readonly||!(node.id===0?props.canCreate:props.canCreate||props.canUpdate||props.canDelete))return;const count=node.id===0?1:Number(props.canCreate)+Number(props.canUpdate)+Number(props.canDelete);const height=count*34+32,width=120;const isPointer=event.type==='contextmenu'&&(event.clientX||event.clientY);const row=!isPointer&&event.type==='contextmenu'&&event.target instanceof Element?event.target.closest('.el-tree-node__content')?.getBoundingClientRect():null;const rect=row??event.currentTarget?.getBoundingClientRect?.();const x=isPointer?event.clientX:(rect?.right??200)-width;const y=isPointer?event.clientY:(rect?.bottom??40)+4;menu.value={node,x:Math.max(8,Math.min(x,window.innerWidth-width-8)),y:Math.max(8,Math.min(y,window.innerHeight-height-8))}}
function action(command){const node=menu.value?.node;menu.value=null;if(node)emit('action',command,node)}
function dropped(){const plain=node=>({id:node.data.id,children:node.childNodes.map(plain)});emit('sort',flattenTree(tree.value.getNode(0).childNodes.map(plain)))}
function outside(e){if(e.target instanceof Element&&e.target.closest('.shared-directory-menu,.shared-directory-trigger'))return;menu.value=null}
function key(e){if(e.key==='Escape')menu.value=null}
function close(){menu.value=null}
onMounted(()=>{document.addEventListener('pointerdown',outside);document.addEventListener('keydown',key);window.addEventListener('resize',close);window.addEventListener('scroll',close,true)})
onBeforeUnmount(()=>{document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',key);window.removeEventListener('resize',close);window.removeEventListener('scroll',close,true)})
</script>
<template><aside class="directory-pane"><el-tree ref="tree" class="directory-tree" :data="treeData" node-key="id" :props="{label:'name',children:'children'}" default-expand-all highlight-current :current-node-key="selected" :draggable="!readonly&&canUpdate" :allow-drag="node=>node.data.id!==0" :allow-drop="(drag,node,type)=>node.data.id!==0||type==='inner'" @node-click="select" @node-contextmenu="open" @node-drop="dropped"><template #default="{data}"><span class="tree-node"><svg v-if="data.id!==0" class="directory-folder-icon" viewBox="0 0 16 14" aria-hidden="true"><path d="M1 2.5c0-.8.7-1.5 1.5-1.5h3l1.6 1.7h6.4c.8 0 1.5.7 1.5 1.5v7.1c0 .9-.7 1.6-1.6 1.6H2.6c-.9 0-1.6-.7-1.6-1.6Z"/><path class="folder-highlight" d="M1.4 4.1h13"/></svg><span class="tree-label" :title="data.name">{{data.name}}</span><button v-if="!readonly&&(data.id===0?canCreate:canCreate||canUpdate||canDelete)" type="button" class="shared-directory-trigger" :aria-label="`${data.name}目录操作`" aria-haspopup="menu" @pointerdown.stop @click.stop="open($event,data)" @contextmenu.stop.prevent="open($event,data)">⋯</button></span></template></el-tree><Teleport to="body"><div v-if="menu" class="shared-directory-menu" role="menu" :aria-label="`${rootLabel}操作`" :style="{left:`${menu.x}px`,top:`${menu.y}px`}" @pointerdown.stop><button v-if="canCreate" type="button" role="menuitem" class="directory-context-item" @click="action('add')"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M1.7 4.2c0-.8.6-1.4 1.4-1.4h2.6l1.4 1.5h5.8c.8 0 1.4.6 1.4 1.4v5.6c0 .8-.6 1.4-1.4 1.4H3.1c-.8 0-1.4-.6-1.4-1.4Z"/><path d="M8 6.2v4.2M5.9 8.3h4.2"/></svg>{{menu.node.id?'新增子目录':'新增目录'}}</button><span v-if="menu.node.id&&canCreate&&(canUpdate||canDelete)" class="divider" role="separator"/><button v-if="menu.node.id&&canUpdate" type="button" role="menuitem" class="directory-context-item" @click="action('rename')"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="m3 10.9-.7 2.8 2.8-.7 7.3-7.3a1.5 1.5 0 0 0-2.1-2.1Z"/><path d="m9.4 4.5 2.1 2.1"/></svg>重命名</button><button v-if="menu.node.id&&canDelete" type="button" role="menuitem" class="directory-context-item danger" @click="action('delete')"><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M2.5 4.2h11M6 4.2V2.7h4v1.5M4.3 4.7l.6 8.1h6.2l.6-8.1M6.4 6.5v4.5M9.6 6.5v4.5"/></svg>删除</button></div></Teleport></aside></template>
<style scoped>
.directory-pane{display:flex;flex:0 0 clamp(180px,15%,210px);flex-direction:column;min-width:0;min-height:0;overflow:hidden;background:#fff;border:1px solid var(--el-border-color-lighter);border-radius:4px;padding:12px}.directory-tree{flex:1;min-height:0;overflow:auto}.tree-node{display:flex;align-items:center;gap:6px;flex:1;min-width:0}.tree-label{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.directory-folder-icon{width:15px;height:14px;flex:none;color:#c3c9d1;fill:currentColor}.folder-highlight{fill:none;stroke:#fff;stroke-opacity:.72;stroke-width:.85}.directory-tree :deep(.el-tree-node.is-current > .el-tree-node__content) .directory-folder-icon{color:#4282c1}.shared-directory-trigger{display:inline-flex;align-items:center;justify-content:center;width:23px;height:23px;flex:none;margin-left:auto;padding:0;border:0;border-radius:4px;background:transparent;color:#61758e;font-size:19px;line-height:1;opacity:0;cursor:pointer}.directory-tree :deep(.el-tree-node__content:hover) .shared-directory-trigger,.directory-tree :deep(.el-tree-node__content:focus-within) .shared-directory-trigger{opacity:1}.shared-directory-trigger:hover{background:#eaf1fa;color:#2e6eae}.shared-directory-trigger:focus-visible{opacity:1;outline:2px solid rgba(52,120,190,.35);outline-offset:1px}.shared-directory-menu{position:fixed;z-index:3000;width:120px;padding:5px;background:#fff;border:1px solid #dce4ed;border-radius:6px;box-shadow:0 8px 22px rgba(29,48,76,.17)}.directory-context-item{display:flex;align-items:center;gap:8px;width:100%;height:34px;padding:0 8px;border:0;border-radius:4px;background:transparent;color:#43566e;text-align:left;white-space:nowrap;font:inherit;font-size:12px;cursor:pointer}.directory-context-item svg{width:15px;height:15px;flex:none;fill:none;stroke:#7e91a8;stroke-width:1.4;stroke-linecap:round;stroke-linejoin:round}.directory-context-item:hover,.directory-context-item:focus-visible{background:#f0f5fb;color:#2b69ae;outline:none}.directory-context-item.danger,.directory-context-item.danger svg{color:#c75454;stroke:#c75454}.divider{display:block;height:1px;margin:5px 4px;background:#edf0f4}@media(hover:none){.shared-directory-trigger{opacity:1}}@media(max-width:700px){.directory-pane{flex:none;width:100%;max-height:180px}}
</style>
